function amount(id){return Number(($(id).value||'').replace(/[^0-9.-]/g,''))||0}
function parseDate(value){const m=/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(value);if(!m)return null;const d=new Date(+m[3],+m[1]-1,+m[2]);return d.getFullYear()===+m[3]&&d.getMonth()===+m[1]-1&&d.getDate()===+m[2]?d:null}
function updateTotal(){let days=0;const start=parseDate($('storageStart').value),end=parseDate($('storageEnd').value);if(start&&end){const diff=(Date.UTC(end.getFullYear(),end.getMonth(),end.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000;days=diff>=0?Math.round(diff)+1:0}const daily=amount('dailyRate'),flat=amount('storageFlat');$('dailyRate').disabled=flat>0;$('storageFlat').disabled=daily>0;const datesDisabled=flat>0;$('storageStart').disabled=datesDisabled;$('storageEnd').disabled=datesDisabled;const storage=flat||days*daily;const total=storage+['towCharge','tearDown','adminCharge','otherCharge'].reduce((sum,id)=>sum+amount(id),0);const money=n=>'$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});$('chargeTotal').value=money(total);$('storageCalc').textContent=flat>0?'Includes flat storage charge of '+money(flat):'Includes storage charge of '+money(storage)+' for '+days+' '+(days===1?'day':'days');const authorized=amount('chargeLimit')||1500;const over=total>authorized;$('chargeApproval').classList.toggle('over',over);$('chargeApprovalText').textContent='The entered charges exceed '+money(authorized)+'. An email will be sent to the adjuster for approval.'}
