const cal=$('calendarPopover'),monthSelect=$('calendarMonth'),yearSelect=$('calendarYear');let calInput=null,calMonth=new Date().getMonth(),calYear=new Date().getFullYear();
const months=Array.from({length:12},(_,i)=>new Intl.DateTimeFormat('en-US',{month:'long'}).format(new Date(2024,i,1)));months.forEach((name,i)=>{const opt=new Option(name,String(i));monthSelect.add(opt)});
function populateYears(){yearSelect.replaceChildren();for(let y=calYear-100;y<=calYear+20;y++)yearSelect.add(new Option(String(y),String(y)))}
function calendarTodayDate(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const value=type=>Number(parts.find(part=>part.type===type).value);return new Date(value('year'),value('month')-1,value('day'))}
function isFutureCalendarDate(date){return new Date(date.getFullYear(),date.getMonth(),date.getDate()).getTime()>calendarTodayDate().getTime()}
function pastDateOnly(input){return input?.id==='recoveryDate'||!!input?.closest('#assignment')}
function invalidDateEntry(input){const date=parseDate(input.value.trim());return !!input.value.trim()&&(!date||(pastDateOnly(input)&&isFutureCalendarDate(date)))}
function calendarCells(year,month){const offset=new Date(year,month,1).getDay();return Array.from({length:42},(_,index)=>{const date=new Date(year,month,index-offset+1);return {date,adjacent:date.getMonth()!==month,future:isFutureCalendarDate(date)}})}
function drawCalendar(){populateYears();monthSelect.value=String(calMonth);yearSelect.value=String(calYear);const grid=$('calendarGrid');grid.replaceChildren();['Su','Mo','Tu','We','Th','Fr','Sa'].forEach(text=>{const head=document.createElement('span');head.className='calendar-weekday';head.textContent=text;grid.append(head)});const selected=parseDate(calInput?.value||'');for(const {date,adjacent,future} of calendarCells(calYear,calMonth)){const button=document.createElement('button');button.type='button';button.textContent=date.getDate();const blockedFuture=pastDateOnly(calInput)&&future;button.disabled=adjacent||blockedFuture;button.classList.toggle('adjacent-month',adjacent);button.classList.toggle('future-date',blockedFuture);button.setAttribute('aria-label',date.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})+(blockedFuture?', unavailable — future date':adjacent?', outside displayed month':''));if(selected&&date.getTime()===selected.getTime()&&!button.disabled)button.classList.add('selected');if(date.getTime()===calendarTodayDate().getTime())button.classList.add('today');button.addEventListener('click',()=>pickDate(date));grid.append(button)}}
function pickDate(d){if(!calInput||(pastDateOnly(calInput)&&isFutureCalendarDate(d)))return;calInput.value=String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+'/'+d.getFullYear();calInput.dispatchEvent(new Event('input',{bubbles:true}));calInput.dispatchEvent(new Event('change',{bubbles:true}));closeCalendar();calInput.focus()}
function placeCalendar(){if(!calInput)return;const r=calInput.getBoundingClientRect(),w=cal.offsetWidth,h=cal.offsetHeight;cal.style.left=Math.max(12,Math.min(r.left,innerWidth-w-12))+'px';cal.style.top=(r.bottom+h+12<innerHeight?r.bottom+6:Math.max(12,r.top-h-6))+'px'}
function openCalendar(input){if(input.disabled)return;calInput=input;const entered=parseDate(input.value);const date=entered&&!(pastDateOnly(input)&&isFutureCalendarDate(entered))?entered:calendarTodayDate();calMonth=date.getMonth();calYear=date.getFullYear();cal.classList.remove('hidden');drawCalendar();placeCalendar()}
function closeCalendar(){cal.classList.add('hidden')}
function formatDateEntry(value){const digits=value.replace(/\D/g,'').slice(0,8);return digits.slice(0,2)+(digits.length>=2?'/':'')+digits.slice(2,4)+(digits.length>=4?'/':'')+digits.slice(4)}
document.querySelectorAll('.date-field').forEach(input=>{input.maxLength=10;input.addEventListener('input',()=>{const original=input.value,atEnd=input.selectionStart>=original.length-1;const digitCount=(original.slice(0,input.selectionStart||0).match(/\d/g)||[]).length;const formatted=formatDateEntry(original);if(original!==formatted){input.value=formatted;if(!atEnd){let seen=0,pos=0;while(pos<formatted.length&&seen<digitCount){if(/\d/.test(formatted[pos]))seen++;pos++}if(formatted[pos]==='/')pos++;input.setSelectionRange(pos,pos)}}});input.addEventListener('keydown',e=>{if(e.key==='Backspace'&&input.selectionStart===input.selectionEnd&&input.selectionStart>0&&input.value[input.selectionStart-1]==='/'){e.preventDefault();const position=input.selectionStart;const before=(input.value.slice(0,position).match(/\d/g)||[]).length;const digits=input.value.replace(/\D/g,'');input.value=formatDateEntry(digits.slice(0,before-1)+digits.slice(before));const next=Math.max(0,position-2);input.setSelectionRange(next,next);input.dispatchEvent(new Event('input',{bubbles:true}))}});const wrap=document.createElement('div');wrap.className='date-wrap';input.parentNode.insertBefore(wrap,input);wrap.append(input);const b=document.createElement('button');b.type='button';b.className='date-trigger';b.setAttribute('aria-label','Choose date');b.innerHTML='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></svg>';wrap.append(b);b.addEventListener('click',()=>{if(calInput===input&&!cal.classList.contains('hidden'))closeCalendar();else openCalendar(input)});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openCalendar(input)}});input.addEventListener('blur',()=>{const d=parseDate(input.value);if(d)input.value=String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+'/'+d.getFullYear()})});
$('calendarPrev').addEventListener('click',()=>{calMonth--;if(calMonth<0){calMonth=11;calYear--}drawCalendar()});$('calendarNext').addEventListener('click',()=>{calMonth++;if(calMonth>11){calMonth=0;calYear++}drawCalendar()});monthSelect.addEventListener('change',()=>{calMonth=+monthSelect.value;drawCalendar()});yearSelect.addEventListener('change',()=>{calYear=+yearSelect.value;drawCalendar()});$('calendarToday').addEventListener('click',()=>pickDate(calendarTodayDate()));$('calendarClear').addEventListener('click',()=>{if(calInput){calInput.value='';calInput.dispatchEvent(new Event('input',{bubbles:true}))}closeCalendar()});document.addEventListener('pointerdown',e=>{if(!cal.contains(e.target)&&!e.target.closest('.date-wrap'))closeCalendar()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCalendar()});window.addEventListener('resize',placeCalendar);window.addEventListener('scroll',()=>{if(!cal.classList.contains('hidden'))placeCalendar()},true);
