function updateReview(){syncBusinessCharges();document.querySelectorAll('.step').forEach(step=>{if(!step.dataset.label)step.dataset.label=step.querySelector('.step-title')?.textContent.trim()||step.textContent.trim()});if($('reviewDestination')){$('reviewDestination').textContent=$('destinationStreet').value.trim()||'Not entered';$('reviewDestinationLocality').textContent=[$('destinationCity').value.trim(),$('destinationState').value].filter(Boolean).join(', ')+($('destinationZip').value.trim()?' '+$('destinationZip').value.trim():'')}const showDocStep=!transportationSelected()&&[...$('documents').querySelectorAll('.pill')].some(p=>p.querySelector('button.on')?.textContent==='Yes');document.querySelector('.step[href="#documents"]').classList.toggle('hidden',!showDocStep);const claim=$('claimNumber').value,first=$('ownerFirst').value,last=$('ownerLast').value;const vehicle=[$('vehicleYear').value,$('vehicleMake').value,$('vehicleModel').value].filter(Boolean).join(' ');$('reviewClaim').textContent=summaryValue(claim);$('reviewOwner').textContent=summaryValue(document.querySelector('[data-seg="owner"] button.on')?.textContent==='Business'?first:[first,last].filter(Boolean).join(' '));const vin=$('vin').value.trim();$('reviewVehicle').textContent=vehicle||'Not entered';$('reviewVin').textContent=vehicle||vin?'VIN: '+(vin||'Not provided'):'';const street=$('pickupStreet').value.trim(),city=$('pickupCity').value.trim(),state=missing($('pickupState'))?'':$('pickupState').value,zip=$('pickupZip').value.trim();const locality=[city,state].filter(Boolean).join(', ')+(zip?' '+zip:'');$('reviewPickup').textContent=summaryValue(street);$('reviewLocality').textContent=locality.trim();$('reviewCharges').textContent=businessChargesApply()&&$('chargesOption').value==='Yes'?'Authorized to Pay':'Not Authorized';const docs=[];document.querySelectorAll('.pill').forEach(p=>{if(p.querySelector('button.on')?.textContent==='Yes')docs.push(p.dataset.target==='lienDoc'?'Lienholder':'Owner')});$('reviewDocuments').textContent=transportationSelected()?'Not applicable':docs.length?docs.join(' and '):'Not requested';let completeCount=0;document.querySelectorAll('.step').forEach(step=>{const section=$(step.hash.slice(1));const controls=section?.classList.contains('card')?requiredControls(section):[];const done=section?.classList.contains('card')&&sectionComplete(section);const documentChoice=!transportationSelected()&&section?.id==='documents'&&[...section.querySelectorAll('.pill')].some(p=>p.querySelector('button.on')?.textContent==='Yes');const needs=(controls.length>0||documentChoice)&&section?.classList.contains('card')&&sectionHasError(section)&&(section.dataset.visited==='yes'||documentChoice||[...section.querySelectorAll('.invalid')].some(control=>visible(control)));step.classList.toggle('complete',!!done);step.classList.toggle('needs-attention',!!needs);const label=step.dataset.label||step.textContent.trim();const status=step.querySelector('.step-state');if(status)status.textContent=needs?'Missing Information':done?'Complete':'';step.classList.toggle('has-status',!!status?.textContent);step.setAttribute('aria-label',label+(needs?', required information missing':done?', complete':''));if(done&&['assignment','people','vehicle','location','pickup','charges',...(transportationSelected()?['destination']:[])].includes(section.id))completeCount++});const documentsIncomplete=documentChoicePending();const totalSections=(transportationSelected()?7:6)-(businessChargesApply()?0:1);const ready=completeCount>=totalSections&&!documentsIncomplete;$('reviewStatus').textContent=documentsIncomplete?'Document assistance incomplete':ready?'Ready to submit':'';$('reviewStatus').classList.toggle('hidden',!documentsIncomplete&&!ready);$('reviewStatus').classList.toggle('ready',ready);updateAssignmentProgressBar()}
$('readyForPickup').addEventListener('click',()=>{$('pickup').dataset.engaged='yes';updateReview()});
document.querySelectorAll('.card').forEach(section=>{section.addEventListener('input',()=>{section.dataset.engaged='yes';updateReview()});section.addEventListener('change',()=>{section.dataset.engaged='yes';updateReview()});section.addEventListener('click',e=>{if(e.target.closest('.seg,.pill,#decode,#uploadImages')){section.dataset.engaged='yes';queueMicrotask(updateReview)}})});
document.querySelectorAll('.field').forEach(field=>{if(!field.querySelector('label .req'))return;const control=field.querySelector('input,select,textarea');if(!control)return;control.addEventListener('blur',()=>{if(!visible(control))return;const bad=missing(control)||(control.classList.contains('date-field')&&invalidDateEntry(control));control.classList.toggle('invalid',!!bad);if(bad)control.setAttribute('aria-invalid','true');else control.removeAttribute('aria-invalid');field.closest('.card')?.setAttribute('data-engaged','yes');updateReview()})});
