const steps=[...document.querySelectorAll('.step')];let activeStepIndex=0;
function activateStep(index){if(index<0||index>=steps.length)return;const visible=steps.filter(step=>!step.classList.contains('hidden'));if(steps[index].classList.contains('hidden')){const fallback=visible.filter(step=>steps.indexOf(step)<index).at(-1)||visible[0];index=steps.indexOf(fallback)}if(index!==activeStepIndex){const previous=$(steps[activeStepIndex].hash.slice(1));if(previous?.classList.contains('card'))previous.dataset.visited='yes';activeStepIndex=index}steps.forEach((step,n)=>{const active=n===index;step.classList.toggle('active',active);if(active)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current')});updateReview()}
steps.forEach((step,index)=>step.addEventListener('click',()=>activateStep(index)));
document.querySelectorAll('#documents .pill button').forEach(button=>button.addEventListener('click',()=>setTimeout(()=>{updateReview();const docIndex=steps.findIndex(step=>step.hash==='#documents');if(!steps[docIndex].classList.contains('hidden'))activateStep(docIndex);else if(activeStepIndex===docIndex)activateStep(docIndex-1)},0)));
const observer=new IntersectionObserver(entries=>{const current=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(current){const index=steps.findIndex(step=>step.hash==='#'+current.target.id);activateStep(index)}},{rootMargin:'-105px 0px -68% 0px'});document.querySelectorAll('.card, #review').forEach(section=>observer.observe(section));

