function setAssignmentType(type){if(!['Standard','Transport Only'].includes(type))return;assignmentType=type;const transport=transportationSelected();$('typeStandard').classList.toggle('selected',!transport);$('typeTransportation').classList.toggle('selected',transport);$('typeStandard').setAttribute('aria-pressed',String(!transport));$('typeTransportation').setAttribute('aria-pressed',String(transport));$('assignmentEntryTitle').textContent=transport?'Transport Only Assignment':'Standard Assignment';$('reviewBtn').textContent=transport?'Submit Transport Only Assignment':'Submit Assignment';$('assignmentTypeStatus').textContent=type+' assignment selected. Shared information has been retained.';$('transportationNote').classList.toggle('hidden',!transport);$('destination').classList.toggle('hidden',!transport);document.querySelector('.step[href="#destination"]').classList.toggle('hidden',!transport);$('documents').classList.toggle('hidden',transport);$('reviewDocumentWrap').classList.toggle('hidden',transport);$('reviewDestinationWrap').classList.toggle('hidden',!transport);$('assignment').querySelector('h2').textContent=transport?'Insurance Company Information':'Seller Information';$('saveStatus').style.display='none';updateReview();activateStep(0)}
