function hideTransportationHelp(){transportationHelpPinned=false;transportationTooltip.classList.add('hidden');transportationHelp.setAttribute('aria-expanded','false')}
transportationHelp.addEventListener('pointerenter',showTransportationHelp);transportationHelp.addEventListener('focus',showTransportationHelp);
transportationHelp.addEventListener('pointerleave',event=>{if(!transportationHelpPinned&&!transportationTooltip.contains(event.relatedTarget)&&document.activeElement!==transportationHelp)hideTransportationHelp()});
