// Browser-local prototype storage. Replace with authenticated server uploads in production.
let pickupDocumentFiles=[],pickupDocumentDatabase=null,pickupDocumentsLoaded=false,pickupDocumentWork=Promise.resolve();
const pickupDocumentTypes=["Pickup Release Document", "Title", "Hold Harmless", "Miscellaneous Document", "Police Release"];
const pickupDocumentKey=file=>JSON.stringify([file.name,file.size,file.lastModified]);
function pickupDocumentFeedback(message,error=false){$('pickupDocumentsFeedback').textContent=message;$('pickupDocumentsFeedback').classList.toggle('error',error)}
function drawPickupDocuments(){const list=$('pickupDocumentsList');list.replaceChildren();pickupDocumentFiles.forEach(item=>{const row=document.createElement('li');row.className='pickup-document-row';const copy=document.createElement('div');copy.className='pickup-document-copy';const name=document.createElement('span');name.className='pickup-document-name';name.textContent=item.file.name;const meta=document.createElement('span');meta.className='pickup-document-meta';const size=item.file.size>=1048576?(item.file.size/1048576).toFixed(1)+' MB':Math.max(1,Math.ceil(item.file.size/1024))+' KB';meta.textContent=size+' · '+(item.saved?'Auto-saved in this browser':'Not saved yet');copy.append(name,meta);const remove=document.createElement('button');remove.type='button';remove.className='pickup-document-delete';remove.textContent='Delete';remove.setAttribute('aria-label','Delete '+item.file.name);remove.addEventListener('click',()=>queuePickupDocumentWork(()=>deletePickupDocument(item.key)));const typeLabel=document.createElement('label');typeLabel.className='pickup-file-type';const typeTitle=document.createElement('span');typeTitle.textContent='Document Type';const select=document.createElement('select');select.setAttribute('aria-label','Document type for '+item.file.name);select.add(new Option('',''));pickupDocumentTypes.forEach(type=>select.add(new Option(type,type)));select.value=item.documentType||'';select.classList.toggle('recorded',!!item.documentType);const typeStatus=document.createElement('span');typeStatus.className='pickup-type-status'+(item.documentType&&item.saved?' recorded':'');typeStatus.textContent=item.documentType?(item.saved?'✓ Document Added':'Type Not Saved'):'Select a document type';select.addEventListener('change',()=>{const value=select.value;queuePickupDocumentWork(()=>setPickupDocumentType(item.key,value))});typeLabel.append(typeTitle,select,typeStatus);row.append(copy,typeLabel,remove);list.append(row)});$('pickupDocumentsClear').classList.toggle('hidden',!pickupDocumentFiles.length);$('pickupDocumentsCount').textContent=pickupDocumentFiles.length+' '+(pickupDocumentFiles.length===1?'Document':'Documents');$('pickupDocumentsCount').classList.toggle('hidden',!pickupDocumentFiles.length)}
function openPickupDocumentDatabase(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('Storage unavailable'));return}const request=indexedDB.open('iv-auto-pickup-document-preview',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Storage blocked'))})}
function pickupDocumentStore(mode,operation){return new Promise((resolve,reject)=>{if(!pickupDocumentDatabase){reject(new Error('Storage unavailable'));return}const tx=pickupDocumentDatabase.transaction('files',mode);const request=operation(tx.objectStore('files'));let result;request.onsuccess=()=>{result=request.result};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage aborted'))})}
function queuePickupDocumentWork(operation){pickupDocumentWork=pickupDocumentWork.then(operation).catch(()=>pickupDocumentFeedback('This change could not be saved. Please try again.',true));return pickupDocumentWork}
async function addPickupDocuments(files){let rejected=0,duplicate=0;for(const file of files){if(!/\.(pdf|jpe?g|png|docx?)$/i.test(file.name)||file.size>20*1048576){rejected++;continue}const key=pickupDocumentKey(file);const existing=pickupDocumentFiles.find(item=>item.key===key);if(existing?.saved){duplicate++;continue}const item=existing||{key,file,saved:false};if(!existing)pickupDocumentFiles.push(item);drawPickupDocuments();try{await pickupDocumentStore('readwrite',store=>store.put({key,file,documentType:item.documentType||''}));item.saved=true}catch{}drawPickupDocuments()}const unsaved=pickupDocumentFiles.some(item=>!item.saved);pickupDocumentFeedback([unsaved?'Some files could not be auto-saved. Keep this page open and select those files again to retry.':files.length?'Documents auto-saved in this browser.':'',rejected?'Some files were skipped. Use a supported format and keep each file under 20 MB.':'',duplicate?'Duplicate files were skipped.':''].filter(Boolean).join(' '),unsaved||rejected>0)}
async function setPickupDocumentType(key,documentType){const item=pickupDocumentFiles.find(item=>item.key===key);if(!item||documentType&&!pickupDocumentTypes.includes(documentType))return;try{await pickupDocumentStore('readwrite',store=>store.put({key,file:item.file,documentType}));item.documentType=documentType;item.saved=true;drawPickupDocuments();pickupDocumentFeedback('Document type auto-saved in this browser.')}catch{pickupDocumentFeedback('The document type could not be saved. Please select it again to retry.',true);drawPickupDocuments()}}
async function deletePickupDocument(key){const item=pickupDocumentFiles.find(item=>item.key===key);if(!item)return;if(item.saved){try{await pickupDocumentStore('readwrite',store=>store.delete(key))}catch{pickupDocumentFeedback('The document could not be deleted. Please try again.',true);return}}pickupDocumentFiles=pickupDocumentFiles.filter(item=>item.key!==key);drawPickupDocuments();pickupDocumentFeedback('Document deleted.')}
async function clearPickupDocuments(){if(pickupDocumentFiles.some(item=>item.saved)){try{await pickupDocumentStore('readwrite',store=>store.clear())}catch{pickupDocumentFeedback('Documents could not be deleted. Please try again.',true);return false}}pickupDocumentFiles=[];drawPickupDocuments();pickupDocumentFeedback('All pickup documents deleted.');return true}
async function startNewAssignment(){await pickupDocumentWork;if(await clearPickupDocuments())window.location.reload()}
$('pickupDocumentsBrowse').addEventListener('click',()=>$('pickupDocumentsInput').click());$('pickupDocumentsInput').addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';queuePickupDocumentWork(()=>addPickupDocuments(files))});$('pickupDocumentsClear').addEventListener('click',()=>queuePickupDocumentWork(clearPickupDocuments));
const pickupDocumentsDrop=$('pickupDocumentsDrop');pickupDocumentsDrop.addEventListener('dragover',e=>{e.preventDefault();if(pickupDocumentsLoaded)pickupDocumentsDrop.classList.add('dragging')});pickupDocumentsDrop.addEventListener('dragleave',()=>pickupDocumentsDrop.classList.remove('dragging'));pickupDocumentsDrop.addEventListener('drop',e=>{e.preventDefault();pickupDocumentsDrop.classList.remove('dragging');if(pickupDocumentsLoaded){const files=[...e.dataTransfer.files];queuePickupDocumentWork(()=>addPickupDocuments(files))}});
(async()=>{try{pickupDocumentDatabase=await openPickupDocumentDatabase();const stored=await pickupDocumentStore('readonly',store=>store.getAll());pickupDocumentFiles=stored.map(item=>({...item,saved:true}));drawPickupDocuments();pickupDocumentFeedback(stored.length?'Saved pickup documents restored.':'')}catch{pickupDocumentFeedback('Browser auto-save is unavailable. Files can be selected for this preview, but will not be retained after a refresh.',true)}finally{pickupDocumentsLoaded=true;$('pickupDocumentsBrowse').disabled=false;$('pickupDocumentsInput').disabled=false}})();

