function formatDollarEntry(value,finalize=false){const raw=value.replace(/[$,\s]/g,'');if(!raw)return '';if(!/^\d*(\.\d{0,2})?$/.test(raw))return value;if(raw==='.')return '$0.';const number=Number(raw);if(!Number.isFinite(number))return value;if(finalize)return '$'+number.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});const parts=raw.split('.');return '$'+Number(parts[0]||0).toLocaleString('en-US',{maximumFractionDigits:0})+(parts.length>1?'.'+parts[1]:'')}
['actualCashValue', 'estimatedRepairCost', 'documentAssistanceAcv'].forEach(id=>{const input=$(id);if(!input)return;input.addEventListener('input',()=>{const old=input.value,position=input.selectionStart??old.length,atEnd=position===old.length,count=(old.slice(0,position).match(/[\d.]/g)||[]).length;input.value=formatDollarEntry(old);if(!atEnd){let seen=0,next=0;while(next<input.value.length&&seen<count){if(/[\d.]/.test(input.value[next]))seen++;next++}input.setSelectionRange(next,next)}updateReview()});input.addEventListener('blur',()=>{input.value=formatDollarEntry(input.value,true);updateReview()})});
